-- ============================================================
-- 外研社九上 wy9A 听力灌库(junior_listening_exercises)· publisher=junior_fltrp · volume=wy9A · grade=9
-- 36 篇 = 6 单元 × 6(3 对话 + 2 独白 + 1 通知),每篇 2 题 4 选 1。
-- UK 英音单音色 speaker=fable;audio_url 先全 NULL,跑 pregenerate --volume=wy9A --speed=0.95 后回填。
-- 语法承载按单元序累积解禁:
--   U1 条件(if)+原因(because/since)
--   U2 时间(when/before/after/until/as soon as)+地点(where/wherever)
--   U3 目的(so that)+结果(so/such…that)
--   U4 who/whom 定语从句
--   U5 that/which 定语从句 + 引导词省略
--   U6 构词法(派生·转化·合成)
-- 全部经 clause_gate / past_perfect_gate / comparative_gate / 词表超前(含豁免表)四门,
--   以及体裁配比、答案分布、听力×阅读与听力×听力 8-gram 雷同检查;36 篇均已经 Aaron 逐批审核通过。
-- id 由 md5(volume|unit|title) 派生(非随机),重跑生成器与重跑 load 都不会产生幽灵行。
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy9A' 双限★
-- ============================================================

BEGIN;

-- 事务开始前先给「本册以外的全部听力行数」拍个快照,收口时逐数比对(见断言⑧)
CREATE TEMP TABLE _wy9a_guard ON COMMIT DROP AS
SELECT count(*) AS n FROM public.junior_listening_exercises
 WHERE NOT (publisher='junior_fltrp' AND volume='wy9A');

DELETE FROM public.junior_listening_exercises
 WHERE publisher='junior_fltrp' AND volume='wy9A';

INSERT INTO public.junior_listening_exercises
  (id, grade, publisher, volume, unit, title, topic, transcript, translation_cn, audio_url, speaker, kind, duration_sec, difficulty, questions, key_vocab) VALUES
  -- U1 dialogue《The morning run》84 词 · 42 秒
  ('c13156f7-36bb-d900-cc24-1b73807b5e41', 9, 'junior_fltrp', 'wy9A', 'U1', 'The morning run', '晨跑(if 条件 · because/since 原因)', 'A: You look tired, Lin. Did you run this morning?
B: Yes. I get up at six every day because I want to be fit for the school sports day.
A: Six! I could never do that.
B: You can, if you start with ten minutes.
A: But it is so cold now.
B: Since we both live near the park, come with me tomorrow. It is easier with a friend.
A: All right. If you knock on my door, I will get up.', 'A:你看起来好累,林。你今早跑步了?B:嗯。我每天六点起床,因为我想在校运会上有个好状态。A:六点!我可做不到。B:你可以的,只要从十分钟开始。A:可现在这么冷。B:既然我们都住在公园附近,明天跟我一起吧,有伴儿更容易坚持。A:好。如果你来敲我的门,我就起。', NULL, 'fable', 'dialogue', 42, 1, '[{"type": "choice", "q": "Why does Lin get up at six every day?", "options": ["To be fit for the school sports day.", "To walk the dog.", "To watch the sunrise.", "To finish the homework."], "answer": "A", "explanation": "''I get up at six every day because I want to be fit for the school sports day.''"}, {"type": "choice", "q": "What does Lin suggest doing tomorrow?", "options": ["Running for a whole hour.", "Buying a pair of new shoes.", "Running together, starting with ten minutes.", "Running only at weekends."], "answer": "C", "explanation": "''You can, if you start with ten minutes.'' + ''come with me tomorrow''。"}]'::jsonb, '[{"word": "fit", "cn": "健康的,状态好的"}, {"word": "knock", "cn": "敲(门)"}]'::jsonb),
  -- U1 dialogue《A gift for Ms Wu》68 词 · 34 秒
  ('d7ecd6c7-b200-56fe-ac21-3f286bbc1f7a', 9, 'junior_fltrp', 'wy9A', 'U1', 'A gift for Ms Wu', '教师节礼物(if 条件 · because/since 原因)', 'A: Teachers'' Day is on Friday. What shall we get for Ms Wu?
B: If we all put in five yuan, we can buy some flowers.
A: Flowers die in a week, though.
B: A card, then. Since everyone can write a line, it will mean more.
A: I like that. And it costs almost nothing.
B: Let us start today, because we need time for thirty lines.', 'A:教师节在周五,我们送吴老师什么?B:如果我们每人出五块钱,就能买些花。A:可花一周就谢了。B:那做张卡片吧。既然每个人都能写一句,那更有意义。A:我喜欢这个主意,而且几乎不花钱。B:那今天就开始,因为三十句话需要时间。', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What do they decide to give Ms Wu?", "options": ["A box of fruit.", "A new book.", "Some flowers.", "A card with a line from everyone."], "answer": "D", "explanation": "''A card, then. Since everyone can write a line, it will mean more.''"}, {"type": "choice", "q": "Why do they want to start today?", "options": ["Because Ms Wu is leaving.", "Because they need time for thirty lines.", "Because Friday is a holiday.", "Because the shop closes early."], "answer": "B", "explanation": "''Let us start today, because we need time for thirty lines.''"}]'::jsonb, '[{"word": "put in", "cn": "凑(钱),出(份子)"}, {"word": "line", "cn": "一句话,一行字"}]'::jsonb),
  -- U1 dialogue《Three hours a day》80 词 · 40 秒
  ('f79492b8-f91e-9a96-3519-e3fe05b73575', 9, 'junior_fltrp', 'wy9A', 'U1', 'Three hours a day', '手机使用时间(if 条件 · because/since 原因)', 'A: My mum says I use my phone too much.
B: How many hours a day?
A: About three. But two of them are English videos!
B: Since some of it is study, tell her that. She may agree.
A: And if I leave the phone in the drawer during my homework, she will trust me more.
B: That helps. My parents trust me because I never take my phone to bed.
A: Then I will try your way first.', 'A:我妈说我手机用得太多。B:一天几个小时?A:大概三小时。但其中两小时是英语视频!B:既然有一部分是学习,就跟她说清楚,她可能会同意。A:而且如果我写作业时把手机放进抽屉,她会更信任我。B:那有用。我爸妈信任我,是因为我从不把手机带上床。A:那我先试试你的办法。', NULL, 'fable', 'dialogue', 40, 2, '[{"type": "choice", "q": "How does the boy use two of the three hours?", "options": ["He plays games.", "He watches English videos.", "He calls his friends.", "He reads the news."], "answer": "B", "explanation": "''About three. But two of them are English videos!''"}, {"type": "choice", "q": "Why do B''s parents trust B?", "options": ["Because B pays for the phone.", "Because B has no phone.", "Because B studies late.", "Because B never takes the phone to bed."], "answer": "D", "explanation": "''My parents trust me because I never take my phone to bed.''"}]'::jsonb, '[{"word": "drawer", "cn": "抽屉"}, {"word": "trust", "cn": "信任"}]'::jsonb),
  -- U1 passage《Why I keep a diary》95 词 · 48 秒
  ('3d995e3d-d1cc-96ad-3fd5-416bfac28325', 9, 'junior_fltrp', 'wy9A', 'U1', 'Why I keep a diary', '独白·写日记(if 条件 · because/since 原因)', 'I started my diary two years ago because my grandpa gave me a small blue book. At first I wrote only three lines a day. Some days nothing happened, so I drew a picture instead. Now I write half a page. If I miss a day, I do not worry. Since the book is only for me, there is no wrong way to fill it. Last month I read the first page again and laughed at my old worries. That is the best part of a diary: it shows you how far you have come.', '两年前我开始写日记,因为爷爷给了我一个蓝色小本子。起初我一天只写三行。有些日子什么都没发生,我就画张画代替。现在我写半页。如果哪天漏了,我也不着急。既然这个本子只写给我自己,就没有什么错的写法。上个月我又读了第一页,笑话自己当年的那些烦恼。这就是日记最好的地方:它让你看见自己走了多远。', NULL, 'fable', 'passage', 48, 2, '[{"type": "choice", "q": "Why did the writer start keeping a diary?", "options": ["It was a school task.", "A teacher asked the class to do it.", "A grandpa gave a small blue book.", "A friend kept one too."], "answer": "C", "explanation": "''I started my diary two years ago because my grandpa gave me a small blue book.''"}, {"type": "choice", "q": "What does the writer think is the best part of keeping a diary?", "options": ["It shows how far you have come.", "It can be shown to friends.", "It fills the free time.", "It helps with English."], "answer": "A", "explanation": "''it shows you how far you have come.''"}]'::jsonb, '[{"word": "diary", "cn": "日记(本)"}, {"word": "worry", "cn": "烦恼,担心的事"}]'::jsonb),
  -- U1 passage《Four lines on the stage》116 词 · 58 秒
  ('8c7c0267-6e05-b429-66b9-6bff1e068b79', 9, 'junior_fltrp', 'wy9A', 'U1', 'Four lines on the stage', '独白·第一次上台(if 条件 · because/since 原因)', 'My hands were cold and my heart was loud. It was my first time on the school stage, and I had only four lines to say. Because I was afraid, I looked at the floor for the first two lines. Then I saw my desk mate in the front row. She was smiling and counting with her fingers, and my voice came back. I finished all four lines. Nobody clapped for long, but my teacher told me something. I still remember it: ''You did not run away.'' Since that day I have put my hand up more often in class. If you are afraid of something small, try it once. The second time is always easier.', '我手是凉的,心跳很响。那是我第一次上校园舞台,只有四句台词。因为害怕,前两句我一直看着地板。然后我看见同桌坐在第一排,她在笑,还用手指帮我数着,我的声音就回来了。我把四句都说完了。没人鼓多久掌,但老师跟我说了一句话,我到现在还记得:「你没有逃走。」从那天起,我在课上举手更多了。如果你怕一件小事,就试一次。第二次总会容易些。', NULL, 'fable', 'passage', 58, 3, '[{"type": "choice", "q": "What did the writer do during the first two lines?", "options": ["Looked at the floor.", "Looked at the teacher.", "Walked off the stage.", "Spoke very fast."], "answer": "A", "explanation": "''Because I was afraid, I looked at the floor for the first two lines.''"}, {"type": "choice", "q": "What advice does the writer give at the end?", "options": ["Learn the lines by heart.", "Never go on a stage.", "Ask a friend to speak for you.", "Try the small thing once."], "answer": "D", "explanation": "''If you are afraid of something small, try it once.''"}]'::jsonb, '[{"word": "stage", "cn": "舞台"}, {"word": "desk mate", "cn": "同桌"}, {"word": "clap", "cn": "鼓掌"}, {"word": "row", "cn": "(一)排"}]'::jsonb),
  -- U1 notice《The autumn talent show》82 词 · 41 秒
  ('51e526d2-4a3d-9365-fda2-8f470e3fe1e9', 9, 'junior_fltrp', 'wy9A', 'U1', 'The autumn talent show', '通知·才艺秀报名(if 条件 · because/since 原因)', 'Good afternoon, everyone. This is a notice about the autumn talent show. If you want to take part, put your name on the list outside the music room before Thursday. You may sing, dance, play an instrument or tell a story. Since the hall is small, each act must be under three minutes. Please bring your own instrument, because the school has only one piano. The show starts at four on Friday. Come early if you want a seat in the front.', '同学们下午好。这是一则关于秋季才艺秀的通知。如果你想参加,请在周四之前把名字写在音乐教室外的名单上。你可以唱歌、跳舞、演奏乐器或讲故事。既然礼堂不大,每个节目必须在三分钟以内。请自带乐器,因为学校只有一架钢琴。演出周五四点开始。如果你想坐前排,就早点来。', NULL, 'fable', 'notice', 41, 1, '[{"type": "choice", "q": "Where should students put their names?", "options": ["On the hall door.", "On the classroom door.", "On the list outside the music room.", "In the school office."], "answer": "C", "explanation": "''put your name on the list outside the music room before Thursday.''"}, {"type": "choice", "q": "Why must each act be under three minutes?", "options": ["Because the show starts late.", "Because the hall is small.", "Because there are only ten acts.", "Because the piano is old."], "answer": "B", "explanation": "''Since the hall is small, each act must be under three minutes.''"}]'::jsonb, '[{"word": "talent show", "cn": "才艺秀"}, {"word": "instrument", "cn": "乐器"}, {"word": "act", "cn": "节目"}]'::jsonb),
  -- U2 dialogue《Saving for a bike》77 词 · 38 秒
  ('54a6dee2-7ae4-d5ef-a686-b636000d50d5', 9, 'junior_fltrp', 'wy9A', 'U2', 'Saving for a bike', '攒钱买车(when/after/until 时间 · wherever 地点)', 'A: How much have you saved, Ben?
B: Two hundred yuan. I started when school began in September.
A: The bike costs six hundred. That is a long way to go.
B: I know. I put twenty yuan in the box every Sunday after I get my pocket money.
A: Do you ever take money out?
B: Not until the box is full. That is my rule.
A: Wherever you go, you walk. Now I know why!', 'A:你攒了多少了,本?B:两百块。我是九月开学的时候开始的。A:那辆车要六百,还差得远呢。B:我知道。每周日拿到零花钱之后,我就往盒子里放二十块。A:你会往外拿吗?B:不到盒子装满就不拿,这是我的规矩。A:你不管去哪儿都走路,现在我知道为什么了!', NULL, 'fable', 'dialogue', 38, 1, '[{"type": "choice", "q": "When did Ben start saving?", "options": ["After he saw the bike.", "After his birthday.", "When the summer holiday began.", "When school began in September."], "answer": "D", "explanation": "''I started when school began in September.''"}, {"type": "choice", "q": "What is Ben''s rule about the money?", "options": ["He does not take any out until the box is full.", "He keeps the money at school.", "He takes some out every month.", "He puts in fifty yuan a week."], "answer": "A", "explanation": "''Not until the box is full. That is my rule.''"}]'::jsonb, '[{"word": "save", "cn": "攒钱,储蓄"}, {"word": "rule", "cn": "规矩,规则"}]'::jsonb),
  -- U2 dialogue《The wallet under the seat》83 词 · 42 秒
  ('925ba2b1-48da-1514-2107-342f45920233', 9, 'junior_fltrp', 'wy9A', 'U2', 'The wallet under the seat', '捡到钱包(before/as soon as/when 时间)', 'A: Look, there is a wallet under the seat.
B: Is there a name inside?
A: Yes, and a bus card too. We should take it to the office before we go home.
B: The office closes at five.
A: Then let us go now. As soon as we hand it in, we can tell the driver as well.
B: Good. When my brother lost his wallet last year, someone did the same for him.
A: Then we are only passing it on.', 'A:看,座位底下有个钱包。B:里面有名字吗?A:有,还有一张公交卡。我们该在回家之前把它送到办公室。B:办公室五点关门。A:那现在就去。我们一交上去,就顺便告诉司机。B:好。去年我哥丢钱包的时候,也有人这样帮过他。A:那我们只是把这份好意传下去。', NULL, 'fable', 'dialogue', 42, 2, '[{"type": "choice", "q": "What will they do before they go home?", "options": ["Take the wallet to the office.", "Look for the owner at school.", "Give the wallet to a teacher.", "Put the wallet back."], "answer": "A", "explanation": "''We should take it to the office before we go home.''"}, {"type": "choice", "q": "What happened to B''s brother last year?", "options": ["He worked in the office.", "He found a wallet on a bus.", "He lost his wallet and someone handed it in.", "He lost his bus card at school."], "answer": "C", "explanation": "''When my brother lost his wallet last year, someone did the same for him.''"}]'::jsonb, '[{"word": "wallet", "cn": "钱包"}, {"word": "hand in", "cn": "上交"}]'::jsonb),
  -- U2 dialogue《Ninety yuan for six》80 词 · 40 秒
  ('cc420b08-dd2e-3f12-a530-f4a051dc683a', 9, 'junior_fltrp', 'wy9A', 'U2', 'Ninety yuan for six', '同学聚餐分账(until/after/before 时间)', 'A: That was a good lunch. How much is it in total?
B: Ninety yuan for six people.
A: So fifteen each. Does anyone have change?
B: Wait until I count the coins. I have ten yuan in small coins.
A: I will pay first, and you can send me the money after you get home.
B: Fine. But before we leave, let us check the bill again.
A: You are right. Last time we paid for one extra drink.', 'A:这顿午饭真不错。一共多少钱?B:六个人九十块。A:那每人十五。谁有零钱?B:等我数数硬币。我有十块的零钱。A:我先付,你们到家之后把钱转给我。B:行。不过我们走之前,再核一遍账单。A:你说得对,上次我们多付了一杯饮料的钱。', NULL, 'fable', 'dialogue', 40, 2, '[{"type": "choice", "q": "How much should each person pay?", "options": ["Ten yuan.", "Fifteen yuan.", "Ninety yuan.", "Six yuan."], "answer": "B", "explanation": "''Ninety yuan for six people.'' → ''So fifteen each.''"}, {"type": "choice", "q": "Why does B want to check the bill again?", "options": ["Because A wants to pay alone.", "Because nobody has change.", "Because the lunch was too dear.", "Because last time they paid for one extra drink."], "answer": "D", "explanation": "''Last time we paid for one extra drink.''"}]'::jsonb, '[{"word": "in total", "cn": "总共"}, {"word": "change", "cn": "零钱"}, {"word": "bill", "cn": "账单"}]'::jsonb),
  -- U2 passage《My first ten yuan》106 词 · 53 秒
  ('b044217a-3d28-b80e-c53e-34a52b445d44', 9, 'junior_fltrp', 'wy9A', 'U2', 'My first ten yuan', '独白·第一次挣钱(before/while/when/after/until/wherever)', 'Last summer I earned my first money. Our neighbour asked me to walk her dog every evening while she was in hospital. I got ten yuan a day. Before that summer, all my money came from my parents. The work was not easy. The dog pulled hard, and when it rained I still had to go out. But after two weeks I held three hundred yuan in my hand, and I felt taller. I did not spend it at once. I put it in a red envelope and kept it until my mother''s birthday. Wherever I keep my money now, I always remember that first envelope.', '去年夏天我挣到了第一笔钱。邻居住院期间,请我每天傍晚去遛她的狗,一天十块。在那个夏天之前,我所有的钱都来自父母。这活儿不轻松:狗使劲拽,下雨天我也得出门。但两周之后,我手里攥着三百块,感觉自己长高了。我没有马上花掉,而是装进一个红包,一直存到我妈生日。现在不管我把钱放在哪儿,总会想起那第一个红包。', NULL, 'fable', 'passage', 53, 2, '[{"type": "choice", "q": "What did the writer do to earn the money?", "options": ["Cleaned the street.", "Sold old books.", "Walked a neighbour''s dog.", "Worked in a shop."], "answer": "C", "explanation": "''Our neighbour asked me to walk her dog every evening while she was in hospital.''"}, {"type": "choice", "q": "What did the writer do with the three hundred yuan?", "options": ["Gave it to the neighbour.", "Kept it until the mother''s birthday.", "Put it in a bank.", "Spent it at once."], "answer": "B", "explanation": "''I put it in a red envelope and kept it until my mother''s birthday.''"}]'::jsonb, '[{"word": "earn", "cn": "挣(钱)"}, {"word": "envelope", "cn": "信封,红包"}]'::jsonb),
  -- U2 passage《The first price》107 词 · 54 秒
  ('bfd5000d-3ae6-f947-d473-2d9db921685a', 9, 'junior_fltrp', 'wy9A', 'U2', 'The first price', '独白·比价(before/when/after/until 时间)', 'My father taught me a small trick. Before you buy anything, he said, look at the price of the same thing in two other shops. It sounds slow, but it is not. Last month I wanted a pair of running shoes. The first shop asked three hundred yuan. When I checked online, the same shoes were two hundred and sixty. After I waited five more days, the price fell again, and I bought them for two hundred and thirty. I did not become rich. But I learnt something better: the first price is not always the real price. Now I never pay until I have looked twice.', '爸爸教了我一个小窍门:买任何东西之前,先看看同样的东西在另外两家店卖多少。听起来慢,其实不慢。上个月我想买双跑鞋。第一家店要三百块。我上网一查,同款只要二百六。又等了五天之后,价格又降了,我二百三买下了。我没有因此变富,但我学到了更值钱的东西:第一个价格不一定是真正的价格。现在我不看两遍绝不付钱。', NULL, 'fable', 'passage', 54, 3, '[{"type": "choice", "q": "How much did the writer finally pay for the shoes?", "options": ["Two hundred yuan.", "Three hundred yuan.", "Two hundred and sixty yuan.", "Two hundred and thirty yuan."], "answer": "D", "explanation": "''the price fell again, and I bought them for two hundred and thirty.''"}, {"type": "choice", "q": "What did the writer learn?", "options": ["The first price is not always the real price.", "Running shoes are too dear.", "Waiting is a waste of time.", "Online shops are always cheaper."], "answer": "A", "explanation": "''the first price is not always the real price.''"}]'::jsonb, '[{"word": "trick", "cn": "窍门,诀窍"}, {"word": "price", "cn": "价格"}, {"word": "fall", "cn": "下降"}]'::jsonb),
  -- U2 notice《The class charity sale》95 词 · 48 秒
  ('d99faebe-5e5d-318f-199b-c8ef7f35a50c', 9, 'junior_fltrp', 'wy9A', 'U2', 'The class charity sale', '通知·班级义卖(before/as soon as/when/after · wherever 地点)', 'Good morning. Here is a notice about our class charity sale. Bring your old books and toys to Room 204 before Wednesday, and please clean them first. On Friday afternoon we will set up our tables in the playground, near the big tree. Wherever you put your table, keep the path clear. The sale starts as soon as the last class finishes. When you sell something, write the price and your name in the small notebook. After the sale, all the money will go to a village school in Yunnan. Thank you for your help.', '早上好。这是关于我们班义卖的通知。请在周三之前把旧书和旧玩具送到204室,并先擦干净。周五下午我们在操场大树旁摆桌子。不管你把桌子摆在哪儿,都要把过道留出来。最后一节课一下课,义卖就开始。你卖出东西的时候,把价格和名字写在小本子上。义卖结束之后,所有的钱都会送到云南的一所乡村学校。谢谢大家。', NULL, 'fable', 'notice', 48, 1, '[{"type": "choice", "q": "When should students bring their old books and toys?", "options": ["After the sale.", "As soon as the sale starts.", "Before Wednesday.", "On Friday morning."], "answer": "C", "explanation": "''Bring your old books and toys to Room 204 before Wednesday.''"}, {"type": "choice", "q": "Where will the money go?", "options": ["To the school library.", "To a village school in Yunnan.", "Back to the students.", "To the class party."], "answer": "B", "explanation": "''After the sale, all the money will go to a village school in Yunnan.''"}]'::jsonb, '[{"word": "charity sale", "cn": "义卖"}, {"word": "set up", "cn": "支起,摆好"}, {"word": "path", "cn": "过道,小路"}]'::jsonb),
  -- U3 dialogue《The paper lantern》85 词 · 42 秒
  ('4fdb4c99-2a96-04b2-c8c6-7569cdb48b83', 9, 'junior_fltrp', 'wy9A', 'U3', 'The paper lantern', '手工灯笼(so that 目的 · so…that 结果)', 'A: Grandma is making lanterns again for the spring festival.
B: Does she still make them by hand?
A: Yes. She says the shop ones are so bright that you cannot see the paper.
B: Can she teach us?
A: She wants to. She keeps her old tools in a wooden box so that nothing gets lost.
B: Then let us ask her on Sunday. I want to learn before the old way goes.
A: Good. Bring a friend, so that more people know it.', 'A:奶奶又在做春节的灯笼了。B:她还是手工做吗?A:是啊。她说店里买的太亮了,亮得都看不见纸。B:她能教我们吗?A:她愿意教。她把老工具都放在一个木盒里,免得弄丢。B:那我们周日去问她。我想在这门老手艺消失之前学会。A:好。再带个朋友来,让更多人知道它。', NULL, 'fable', 'dialogue', 42, 1, '[{"type": "choice", "q": "Why does Grandma keep her old tools in a wooden box?", "options": ["So that nothing gets lost.", "So that they look nice.", "Because the box is new.", "Because she sells them."], "answer": "A", "explanation": "''She keeps her old tools in a wooden box so that nothing gets lost.''"}, {"type": "choice", "q": "What does A ask B to do?", "options": ["Make a box at home.", "Buy a lantern in a shop.", "Come alone on Sunday.", "Bring a friend along."], "answer": "D", "explanation": "''Bring a friend, so that more people know it.''"}]'::jsonb, '[{"word": "lantern", "cn": "灯笼"}, {"word": "by hand", "cn": "手工地"}, {"word": "tool", "cn": "工具"}]'::jsonb),
  -- U3 dialogue《The name of our street》85 词 · 42 秒
  ('cd424091-aec8-8648-7827-bcae8634c4fd', 9, 'junior_fltrp', 'wy9A', 'U3', 'The name of our street', '老街名的来历(such…that 结果 · so that 目的)', 'A: Do you know why our street is called Well Street?
B: No. Is there a well?
A: There was one, a hundred years ago. It was such an important well that people came from three villages.
B: And now?
A: It was covered long ago. But the old name stayed, so that we still remember it.
B: I will ask my grandfather. He may have a photo.
A: Please do. If we collect enough photos, we can make a small wall show at school.', 'A:你知道我们这条街为什么叫井街吗?B:不知道。这儿有井吗?A:一百年前有过一口。那口井太重要了,三个村子的人都来打水。B:现在呢?A:很早以前就填上了。但老名字留了下来,好让我们还记得它。B:我去问问我爷爷,他可能有照片。A:一定要问。如果我们收集到足够的照片,就能在学校办一个小型墙展。', NULL, 'fable', 'dialogue', 42, 2, '[{"type": "choice", "q": "Why did people come from three villages?", "options": ["Because the photos were free.", "Because the street was wide.", "Because the well was such an important one.", "Because there was a school."], "answer": "C", "explanation": "''It was such an important well that people came from three villages.''"}, {"type": "choice", "q": "What do they plan to do with the photos?", "options": ["Keep them at home.", "Make a small wall show at school.", "Sell them to a shop.", "Send them to a newspaper."], "answer": "B", "explanation": "''If we collect enough photos, we can make a small wall show at school.''"}]'::jsonb, '[{"word": "well", "cn": "井"}, {"word": "cover", "cn": "盖上,填上"}, {"word": "collect", "cn": "收集"}]'::jsonb),
  -- U3 dialogue《Story day in dialect》86 词 · 43 秒
  ('a1fedbcb-2510-80d7-d1de-bcb82614e5e5', 9, 'junior_fltrp', 'wy9A', 'U3', 'Story day in dialect', '方言故事日(so that 目的 · so…that 结果)', 'A: Our class is holding a story day next week. Every story must be told in our home dialect.
B: My dialect is not very good.
A: Mine is not either. But my mother says she will teach me one short story so that I can try.
B: That is a good idea. My grandfather knows many old sayings.
A: Ask him to write three down. They are so short that you can learn them in one evening.
B: All right. I will call him tonight.', 'A:我们班下周办故事日,每个故事都必须用家乡话讲。B:我方言说得不太好。A:我也不好。不过我妈说她会教我一个小故事,让我能试试。B:这主意不错。我爷爷会很多老话。A:让他写三条下来。那些话很短,短到你一晚上就能学会。B:好,我今晚就给他打电话。', NULL, 'fable', 'dialogue', 43, 2, '[{"type": "choice", "q": "Who will teach A a short story?", "options": ["The class teacher.", "B''s grandfather.", "A''s grandfather.", "A''s mother."], "answer": "D", "explanation": "''my mother says she will teach me one short story so that I can try.''"}, {"type": "choice", "q": "Why does A think the old sayings are easy to learn?", "options": ["Because they are so short.", "Because they are in English.", "Because they are written down.", "Because the grandfather explains them."], "answer": "A", "explanation": "''They are so short that you can learn them in one evening.''"}]'::jsonb, '[{"word": "dialect", "cn": "方言"}, {"word": "saying", "cn": "俗语,老话"}]'::jsonb),
  -- U3 passage《The old roll book》96 词 · 48 秒
  ('692a7a68-9d43-2eca-fb60-8ae0b8e6dfd3', 9, 'junior_fltrp', 'wy9A', 'U3', 'The old roll book', '独白·1958年的点名册(so that 目的 · so…that 结果)', 'Last term our school opened a small room for its own history. On the first table there is a roll book from 1958. The paper is brown and soft, and the names are written with a brush. Our teacher keeps it under glass so that it stays safe. One name is my grandfather''s. He was twelve then, and he walked a long way to school every day. When I stood in front of that book, the past felt so close that I forgot the bell. Now I go there every Friday to read one more page.', '上学期我们学校开了一间小小的校史室。第一张桌上放着一本1958年的点名册。纸是褐色的、软软的,名字是用毛笔写的。老师把它放在玻璃下面,好让它保存完好。其中一个名字是我爷爷的。他那时十二岁,每天走很远的路来上学。当我站在那本册子前面,过去近得让我连铃声都忘了。现在我每周五都去,再读一页。', NULL, 'fable', 'passage', 48, 2, '[{"type": "choice", "q": "What is on the first table in the small room?", "options": ["A glass bell.", "A roll book from 1958.", "A brush from 1958.", "A photo of the writer''s grandfather."], "answer": "B", "explanation": "''On the first table there is a roll book from 1958.''"}, {"type": "choice", "q": "Why does the teacher keep the book under glass?", "options": ["Because the room is small.", "Because the names are new.", "So that it stays safe.", "So that more people buy it."], "answer": "C", "explanation": "''Our teacher keeps it under glass so that it stays safe.''"}]'::jsonb, '[{"word": "roll book", "cn": "点名册"}, {"word": "brush", "cn": "毛笔"}]'::jsonb),
  -- U3 passage《The song my grandmother sings》118 词 · 59 秒
  ('74cfa8e8-a7c7-5235-b674-3877af979b9d', 9, 'junior_fltrp', 'wy9A', 'U3', 'The song my grandmother sings', '独白·奶奶的老调子(so that 目的 · so…that 结果)', 'My grandmother sings while she cooks. The songs are old, and some of them have no name. Last year I asked her to sing one twice so that I could write the words down. She laughed and said that no one ever asks. I filled six pages that winter. The words are simple: rain, rice, a boat, a road home. But the tune is so old that my grandmother learnt it from her own grandmother. Our music teacher heard one of them and put it in the school show, so that a hundred students sang it together. My grandmother sat in the third row and did not sing at all. She only listened, and her eyes were bright.', '我奶奶做饭的时候会唱歌。那些歌很老,有些连名字都没有。去年我请她把一首唱两遍,好让我把词记下来。她笑了,说从来没人问过。那个冬天我记满了六页。词很简单:雨、米、一条船、一条回家的路。可那调子太老了,老到我奶奶是从她自己的奶奶那里学来的。我们音乐老师听到其中一首,把它排进了校演出,于是一百个学生一起唱了它。我奶奶坐在第三排,一句也没唱。她只是听着,眼睛很亮。', NULL, 'fable', 'passage', 59, 3, '[{"type": "choice", "q": "Why did the writer ask grandmother to sing one song twice?", "options": ["So that the family could hear it.", "Because the song was too fast.", "So that the writer could write the words down.", "Because the music teacher asked for it."], "answer": "C", "explanation": "''I asked her to sing one twice so that I could write the words down.''"}, {"type": "choice", "q": "What did the grandmother do at the school show?", "options": ["She listened without singing.", "She stayed at home.", "She sang with the students.", "She taught the music teacher."], "answer": "A", "explanation": "''My grandmother sat in the third row and did not sing at all. She only listened.''"}]'::jsonb, '[{"word": "tune", "cn": "曲调"}, {"word": "fill", "cn": "写满,填满"}]'::jsonb),
  -- U3 notice《History Week》98 词 · 49 秒
  ('1d22452e-7361-df15-f353-584a2a86f43f', 9, 'junior_fltrp', 'wy9A', 'U3', 'History Week', '通知·历史周(so that 目的 · so…that 结果 · because 原因)', 'Good morning. Next week is our History Week. On Monday, bring one old thing from your family: a photo, a coin, a letter or a tool. We will put them on the tables in Room 105 so that everyone can see them. Please write two lines about your thing, because a story is more interesting than an object. On Wednesday an old worker from the paper mill will come to talk to us. His stories are so good that last year nobody left early. On Friday we will choose ten things for the school history room. Thank you.', '早上好。下周是我们的历史周。周一,请从家里带一件老物件来:一张照片、一枚硬币、一封信或一件工具。我们会把它们摆在105室的桌上,好让每个人都能看到。请为你的物件写两句话,因为故事比物件本身更有意思。周三,造纸厂的一位老工人会来跟我们讲他的经历。他的故事太精彩了,去年没有一个人提前离场。周五我们会挑出十件放进校史室。谢谢大家。', NULL, 'fable', 'notice', 49, 1, '[{"type": "choice", "q": "What should students bring on Monday?", "options": ["Ten coins for the school.", "A book about history.", "A new photo of the class.", "One old thing from the family."], "answer": "D", "explanation": "''On Monday, bring one old thing from your family.''"}, {"type": "choice", "q": "Why should students write two lines about their thing?", "options": ["Because there is no room for more.", "Because a story is more interesting than an object.", "Because the show is on Friday.", "Because the teacher will read them out."], "answer": "B", "explanation": "''because a story is more interesting than an object.''"}]'::jsonb, '[{"word": "object", "cn": "物件,东西"}, {"word": "paper mill", "cn": "造纸厂"}]'::jsonb),
  -- U4 dialogue《The doctor by the door》75 词 · 38 秒
  ('590451a7-cb90-e10f-bde0-70424117b190', 9, 'junior_fltrp', 'wy9A', 'U4', 'The doctor by the door', '退休医生义务量血压(who 作主语 · whom 作宾语)', 'A: Who is the man who sits by the door every Saturday morning?
B: That is Dr Zhou. He is a doctor who retired ten years ago.
A: And he still works?
B: Not for money. He checks blood pressure for anyone who comes.
A: For free?
B: For free. My grandmother is one of the people who go every week.
A: He is the kind of person whom our street is lucky to have.', 'A:每周六上午坐在门口的那位是谁?B:那是周医生。他是十年前退休的医生。A:他还在工作?B:不为钱。谁来他就给谁量血压。A:免费吗?B:免费。我奶奶就是每周都去的人之一。A:他就是那种我们这条街有幸拥有的人。', NULL, 'fable', 'dialogue', 38, 1, '[{"type": "choice", "q": "What does Dr Zhou do every Saturday morning?", "options": ["He checks blood pressure for free.", "He works in a big hospital.", "He sells medicine at the door.", "He teaches a class for old people."], "answer": "A", "explanation": "''He checks blood pressure for anyone who comes.'' + ''For free.''"}, {"type": "choice", "q": "Who goes to see Dr Zhou every week?", "options": ["Nobody at all.", "B''s grandmother.", "A''s mother.", "The street cleaner."], "answer": "B", "explanation": "''My grandmother is one of the people who go every week.''"}]'::jsonb, '[{"word": "retire", "cn": "退休"}, {"word": "blood pressure", "cn": "血压"}]'::jsonb),
  -- U4 dialogue《The teacher who stayed》95 词 · 48 秒
  ('1c2ea302-c0a0-3a70-a62f-76c8e60baf42', 9, 'junior_fltrp', 'wy9A', 'U4', 'The teacher who stayed', '乡村教师(who 作主语 · whom 作宾语)', 'A: Our English teacher told us about a teacher who went to a village school twenty years ago.
B: Did he stay long?
A: He is still there. He is the only teacher who teaches all six classes.
B: All six? How does he do it?
A: He teaches maths in the morning and English in the afternoon. The students who leave that school always go back to see him.
B: I would like to write to him.
A: Then write. He is a person whom few people know, but his students never forget him.', 'A:我们英语老师讲了一位二十年前去乡村学校的老师。B:他待了很久吗?A:他还在那儿。他是唯一一个把六个年级都教下来的老师。B:六个年级?他怎么做到的?A:上午教数学,下午教英语。从那所学校毕业的学生总会回去看他。B:我想给他写封信。A:那就写。他是个很少有人知道的人,可他的学生永远不会忘记他。', NULL, 'fable', 'dialogue', 48, 2, '[{"type": "choice", "q": "How many classes does the village teacher teach?", "options": ["None now.", "Only English.", "Two classes.", "Six classes."], "answer": "D", "explanation": "''He is the only teacher who teaches all six classes.''"}, {"type": "choice", "q": "What do the students do after they leave that school?", "options": ["They forget the village.", "They write to the newspaper.", "They go back to see him.", "They send him money."], "answer": "C", "explanation": "''The students who leave that school always go back to see him.''"}]'::jsonb, '[{"word": "village", "cn": "村子,乡村"}, {"word": "few", "cn": "很少的"}]'::jsonb),
  -- U4 dialogue《The man with the yellow box》85 词 · 42 秒
  ('ec65dc9a-0a29-a4cf-8d0a-6510ab8b3146', 9, 'junior_fltrp', 'wy9A', 'U4', 'The man with the yellow box', '送快递的人(who 作主语 · whom 作宾语)', 'A: There is a man who delivers parcels in our street every day. He carries a yellow box.
B: I know him. Last month he stopped to help an old woman who fell near the shop.
A: Really?
B: He waited for her family and lost an hour of work.
A: Did anyone thank him?
B: The woman''s son did. He said he wanted to find the man who helped his mother.
A: Some heroes are people whom we see every day and never notice.', 'A:我们街上有个每天送包裹的人,他背一个黄色的箱子。B:我认识他。上个月他停下来扶了一位在店铺附近摔倒的老人。A:真的?B:他一直等到她家人来,少送了一个小时的活儿。A:有人谢他吗?B:老人的儿子谢了。他说想找到那个帮了他母亲的人。A:有些英雄就是我们天天见到、却从没留意过的人。', NULL, 'fable', 'dialogue', 42, 2, '[{"type": "choice", "q": "What did the delivery man do last month?", "options": ["He lost his yellow box.", "He helped an old woman who fell.", "He asked the shop for money.", "He changed his job."], "answer": "B", "explanation": "''he stopped to help an old woman who fell near the shop.''"}, {"type": "choice", "q": "What does A think at the end?", "options": ["Some heroes are people we never notice.", "Heroes are always famous.", "Heroes work in hospitals.", "Heroes never lose time."], "answer": "A", "explanation": "''Some heroes are people whom we see every day and never notice.''"}]'::jsonb, '[{"word": "deliver", "cn": "投递,送"}, {"word": "parcel", "cn": "包裹"}, {"word": "notice", "cn": "注意到"}]'::jsonb),
  -- U4 passage《The woman who counts birds》107 词 · 54 秒
  ('9ea81fb7-bab9-54a1-82f6-1deb799cc5a2', 9, 'junior_fltrp', 'wy9A', 'U4', 'The woman who counts birds', '独白·数鸟十九年(who 作主语)', 'Every spring a woman who lives near the river gets up at four. She takes a notebook, a pen and a cup of hot tea, and she counts birds. She has done this for nineteen years. Nobody pays her. The scientists who study the river use her numbers, because no computer can sit by the water for nineteen years. Last April she wrote down one name for the first time in twenty years. People who meet her say she talks about the birds like old neighbours. She is not famous, and she does not want to be. She only says one thing: someone has to keep looking.', '每年春天,一位住在河边的女人四点起床。她带上笔记本、一支笔和一杯热茶,去数鸟。这件事她做了十九年,没有人付她钱。研究这条河的科学家们用她的数字,因为没有哪台电脑能在水边坐上十九年。去年四月,她写下了一个二十年来第一次出现的名字。见过她的人说,她谈起那些鸟就像谈起老邻居。她不出名,也不想出名。她只说一句话:总得有人一直看下去。', NULL, 'fable', 'passage', 54, 2, '[{"type": "choice", "q": "How long has the woman counted birds?", "options": ["Since last April.", "Four years.", "Nineteen years.", "Twenty-five years."], "answer": "C", "explanation": "''She has done this for nineteen years.''"}, {"type": "choice", "q": "Why do the scientists use her numbers?", "options": ["Because she is famous.", "Because she works for them.", "Because her numbers are free.", "Because no computer can sit by the water for nineteen years."], "answer": "D", "explanation": "''because no computer can sit by the water for nineteen years.''"}]'::jsonb, '[{"word": "count", "cn": "数,清点"}, {"word": "scientist", "cn": "科学家"}]'::jsonb),
  -- U4 passage《The letter in the drawer》106 词 · 53 秒
  ('937cb6f0-d9c0-319c-2453-33a9265df053', 9, 'junior_fltrp', 'wy9A', 'U4', 'The letter in the drawer', '独白·抽屉里的信(who 作主语 · whom 作宾语)', 'My father is a quiet man who never talks about his work. Last month I found a letter in his drawer. It was from a woman whom he pulled out of a car in 2011. He was driving home from the night shift when he saw the smoke. He broke the window and carried her to the grass. The letter has only four lines. It ends like this: ''My son is nine now. He knows the name of the man who came back for me.'' My father never told us about it. When I asked him, he said that anyone in that place does the same.', '我爸是个从不谈自己工作的沉默的人。上个月我在他抽屉里发现一封信。写信的是2011年被他从车里拉出来的一位女士。那天他上完夜班开车回家,看见了烟。他砸开车窗,把她抱到草地上。信只有四行,结尾是这样写的:「我儿子现在九岁了。他知道那个回头来救我的人叫什么名字。」我爸从没跟我们说过。我问他的时候,他说换成谁在那儿都会这么做。', NULL, 'fable', 'passage', 53, 3, '[{"type": "choice", "q": "Who wrote the letter?", "options": ["The writer''s mother.", "A boy of nine.", "A friend of the father.", "A woman whom the father pulled out of a car."], "answer": "D", "explanation": "''It was from a woman whom he pulled out of a car in 2011.''"}, {"type": "choice", "q": "What did the father say when he was asked about it?", "options": ["He said anyone in that place does the same.", "He said he wanted a reward.", "He said he could not remember.", "He said the letter was not for him."], "answer": "A", "explanation": "''he said that anyone in that place does the same.''"}]'::jsonb, '[{"word": "night shift", "cn": "夜班"}, {"word": "smoke", "cn": "烟"}, {"word": "quiet", "cn": "沉默寡言的"}]'::jsonb),
  -- U4 notice《Our own heroes》103 词 · 52 秒
  ('1bff8e8e-5a37-f286-93cc-d31bfee9dbd8', 9, 'junior_fltrp', 'wy9A', 'U4', 'Our own heroes', '通知·校报征稿(who 作主语 · whom 作宾语)', 'Good afternoon. Here is a notice from the school newspaper. This term we are looking for stories about people who help others near us. The person you write about does not have to be famous. It can be a worker who cleans your building, a cook who remembers what you cannot eat, or a neighbour whom you have known all your life. Write no more than two hundred words and put your story in the red box outside Room 302 before the tenth. Ten stories will be printed, and the writers who send them will get a copy for their families. Thank you.', '下午好。这是校报的一则通知。本学期我们征集身边助人者的故事。你写的人不必有名:可以是打扫你家楼的工人、可以是记得你不能吃什么的食堂师傅,也可以是你认识了一辈子的邻居。字数不超过两百词,在十号之前投进302室外面的红盒子。我们会刊登十篇,投稿被选中的作者会拿到一份给家人留存。谢谢。', NULL, 'fable', 'notice', 52, 1, '[{"type": "choice", "q": "What kind of person should students write about?", "options": ["Someone who is famous in the city.", "Someone who works at the newspaper.", "Someone who helps others near us.", "Someone who lives far away."], "answer": "C", "explanation": "''stories about people who help others near us'' + ''does not have to be famous.''"}, {"type": "choice", "q": "Where should students put their stories?", "options": ["In the newspaper office.", "In the red box outside Room 302.", "On the teacher''s desk.", "In the school library."], "answer": "B", "explanation": "''put your story in the red box outside Room 302 before the tenth.''"}]'::jsonb, '[{"word": "cook", "cn": "厨师,食堂师傅"}, {"word": "print", "cn": "刊登,印刷"}, {"word": "copy", "cn": "一份,一册"}]'::jsonb),
  -- U5 dialogue《The nest above the door》78 词 · 39 秒
  ('2e05c057-0bdc-e538-2f16-13f458fb73cf', 9, 'junior_fltrp', 'wy9A', 'U5', 'The nest above the door', '店门上的燕巢(that 定从 · 省略引导词 · so that)', 'A: Look up. There is a nest above the shop door.
B: Those are swallows. They come back every April.
A: The shop owner did not take it down?
B: No. He put a small board under it, so that nothing falls on people.
A: That is the kind of thing I like about this street.
B: My grandmother says a house that has swallows is a lucky house.
A: Then this shop will have a good year.', 'A:抬头看,店门上面有个窝。B:那是燕子,它们每年四月都回来。A:店主没把它拆掉?B:没有。他在下面钉了块小木板,免得东西掉到人身上。A:这就是我喜欢这条街的地方。B:我奶奶说,有燕子的房子是有福的房子。A:那这家店今年会不错。', NULL, 'fable', 'dialogue', 39, 1, '[{"type": "choice", "q": "What did the shop owner do about the nest?", "options": ["He took it down.", "He put a small board under it.", "He moved it to the roof.", "He called the police."], "answer": "B", "explanation": "''He put a small board under it, so that nothing falls on people.''"}, {"type": "choice", "q": "What does B''s grandmother say?", "options": ["Swallows bring rain.", "Swallows should be fed.", "A house that has swallows is a lucky house.", "Nests are dangerous."], "answer": "C", "explanation": "''a house that has swallows is a lucky house.''"}]'::jsonb, '[{"word": "nest", "cn": "(鸟)巢"}, {"word": "swallow", "cn": "燕子"}, {"word": "board", "cn": "木板"}]'::jsonb),
  -- U5 dialogue《The frogs came back》76 词 · 38 秒
  ('d280cef0-2e20-8d86-8e3e-b4e3b9941ab3', 9, 'junior_fltrp', 'wy9A', 'U5', 'The frogs came back', '青蛙回来了(省略引导词 · which 作主语 · that 定从)', 'A: Did you hear the frogs last night?
B: Yes! The pond we cleaned in March is full of them now.
A: Two years ago there was not a sound.
B: The water which ran into the pond was grey then. Now it is clear.
A: So the frogs are the test.
B: My science teacher says the animals that leave first are the ones we should count.
A: Then let us count them on Saturday.', 'A:你昨晚听见青蛙了吗?B:听见了!我们三月清理的那个池塘现在满是青蛙。A:两年前那里一点声音都没有。B:那时流进池塘的水是灰的,现在清了。A:所以青蛙就是那个检验标准。B:我们科学老师说,最先离开的动物才是我们该去数的。A:那周六我们去数吧。', NULL, 'fable', 'dialogue', 38, 2, '[{"type": "choice", "q": "What is in the pond now?", "options": ["Grey water.", "Nothing at all.", "Many fish.", "A lot of frogs."], "answer": "D", "explanation": "''The pond we cleaned in March is full of them now.''"}, {"type": "choice", "q": "What does the science teacher say?", "options": ["The animals that leave first are the ones we should count.", "Frogs are hard to find.", "Ponds should be cleaned in March.", "Grey water is safe."], "answer": "A", "explanation": "''the animals that leave first are the ones we should count.''"}]'::jsonb, '[{"word": "frog", "cn": "青蛙"}, {"word": "pond", "cn": "池塘"}]'::jsonb),
  -- U5 dialogue《The bird club's first morning》79 词 · 40 秒
  ('11dd0ee4-92a4-47c2-b50d-74db560b06c5', 9, 'junior_fltrp', 'wy9A', 'U5', 'The bird club''s first morning', '观鸟社第一次活动(省略引导词 · which/that 定从)', 'A: Six o''clock is early for a club.
B: Birds do not wait. The book I borrowed says the first hour is the best.
A: What do we write down?
B: The name, the number and the place. The forms which the teacher printed are in my bag.
A: And if we do not know a name?
B: Draw it. A picture that shows the beak and the tail is enough.
A: Then I will need a better pencil.', 'A:社团六点也太早了。B:鸟可不等人。我借的那本书上说,头一个小时最好。A:我们要记什么?B:名字、数量和地点。老师印的表格在我包里。A:要是我们不认识它的名字呢?B:画下来。一张能看出喙和尾巴的图就够了。A:那我得换支好点的铅笔。', NULL, 'fable', 'dialogue', 40, 2, '[{"type": "choice", "q": "Why does the club start at six?", "options": ["The park closes early.", "The teacher is free then.", "The book says the first hour is the best.", "It is cooler then."], "answer": "C", "explanation": "''The book I borrowed says the first hour is the best.''"}, {"type": "choice", "q": "What should they do if they do not know a bird''s name?", "options": ["Ask another club.", "Draw it.", "Leave the line empty.", "Take the bird home."], "answer": "B", "explanation": "''Draw it. A picture that shows the beak and the tail is enough.''"}]'::jsonb, '[{"word": "beak", "cn": "鸟喙"}, {"word": "form", "cn": "表格"}]'::jsonb),
  -- U5 passage《The lights in the grass》99 词 · 50 秒
  ('e218264c-f459-2990-9000-579eb7de9587', 9, 'junior_fltrp', 'wy9A', 'U5', 'The lights in the grass', '独白·萤火虫回来了(which 定从 · 省略引导词)', 'When my mother was a girl, she could see fireflies from her window every summer. By the time I was born, they were gone. The river which runs behind our village was green with waste, and the fields were bright with lamps all night. Three years ago a group of villagers began a small plan. They turned off the lamps along the water from June to August, and they left one strip of grass uncut. Last summer my mother called me to the window. Below us, low over the grass, were the small lights she waited thirty years for.', '我妈小时候,每年夏天都能从窗口看见萤火虫。到我出生的时候,它们已经没了。村后那条河被污水染绿,田里整夜亮着灯。三年前,一群村民开始了一个小计划:六月到八月关掉水边的灯,并留下一条不割的草带。去年夏天,我妈把我叫到窗前。就在我们下面、贴着草面,是她等了三十年的那些小小的光。', NULL, 'fable', 'passage', 50, 3, '[{"type": "choice", "q": "Why did the fireflies disappear?", "options": ["The village grew too small.", "People caught them all.", "The summers became cold.", "The river was full of waste and the lamps were on all night."], "answer": "D", "explanation": "''The river which runs behind our village was green with waste, and the fields were bright with lamps all night.''"}, {"type": "choice", "q": "What did the villagers do?", "options": ["Turned off the lamps in summer and left one strip of grass uncut.", "Built a new river bank.", "Planted trees along the road.", "Moved the fields."], "answer": "A", "explanation": "''They turned off the lamps along the water from June to August, and they left one strip of grass uncut.''"}]'::jsonb, '[{"word": "firefly", "cn": "萤火虫"}, {"word": "waste", "cn": "废水,废物"}, {"word": "strip", "cn": "(狭长的)一条"}]'::jsonb),
  -- U5 passage《The bird in the box》106 词 · 53 秒
  ('40a26039-1233-09c7-bcec-5414cb61ed7b', 9, 'junior_fltrp', 'wy9A', 'U5', 'The bird in the box', '独白·受伤的鸟(who/that/which 定从并置)', 'Last October I found a bird on the road behind our school. It could not fly. A woman who walks her dog there told me not to touch it with bare hands, so I used my coat. We took it to a small centre that looks after wild animals. The man at the desk asked three questions: where I found it, what time it was, and whether there were cats nearby. He wrote everything down. Six weeks later he sent us a photo. The bird which I carried in my coat was standing on a branch, and the message under the photo said one word: released.', '去年十月,我在学校后面的路上发现一只鸟,它飞不起来。一位在那儿遛狗的女士让我别用手直接碰它,于是我用外套裹住了它。我们把它送到一个照顾野生动物的小站。柜台的人问了三个问题:在哪儿发现的、几点、附近有没有猫。他把每一条都记了下来。六周后他发来一张照片:我用外套抱过的那只鸟正站在树枝上,照片下面只有一个词——已放归。', NULL, 'fable', 'passage', 53, 2, '[{"type": "choice", "q": "What did the woman tell the writer to do?", "options": ["Take the bird home.", "Leave the bird alone.", "Not to touch it with bare hands.", "Call the school office."], "answer": "C", "explanation": "''A woman who walks her dog there told me not to touch it with bare hands.''"}, {"type": "choice", "q": "What did the message under the photo say?", "options": ["Released.", "Sorry.", "Still ill.", "Thank you."], "answer": "A", "explanation": "''the message under the photo said one word: released.''"}]'::jsonb, '[{"word": "bare", "cn": "赤裸的,不戴手套的"}, {"word": "wild", "cn": "野生的"}, {"word": "release", "cn": "放归,释放"}]'::jsonb),
  -- U5 notice《Nature Watch Week》102 词 · 51 秒
  ('06d0d0f1-4a7f-4105-0de5-dc881e1ac96b', 9, 'junior_fltrp', 'wy9A', 'U5', 'Nature Watch Week', '通知·自然观察周(which/that 定从 · 省略引导词)', 'Good morning. Next week is Nature Watch Week. Every class will take one small place in the school and watch it for five days: a corner of the garden, the pond by the gate, or the wall which faces the playground. Write down what you see, not what you expect. The forms you need are on the shelf outside Room 108. Do not move nests, and do not feed any animal. On Friday afternoon each class will show the list they made. The class that finds the most kinds of living things will keep the green flag for a term. Thank you.', '早上好。下周是自然观察周。每个班在校园里选一小块地方,连续观察五天:花园的一角、校门旁的池塘,或者朝着操场的那面墙。记下你看到的,而不是你以为会看到的。你们需要的表格在108室外面的架子上。不要移动鸟巢,不要投喂任何动物。周五下午每个班展示自己做的清单。发现物种最多的班级将保管绿旗一个学期。谢谢。', NULL, 'fable', 'notice', 51, 1, '[{"type": "choice", "q": "What should students write down?", "options": ["Only the names of birds.", "What they see, not what they expect.", "The weather of each day.", "The number of students."], "answer": "B", "explanation": "''Write down what you see, not what you expect.''"}, {"type": "choice", "q": "What will the winning class get?", "options": ["A new garden.", "A free trip.", "Ten forms.", "The green flag for a term."], "answer": "D", "explanation": "''The class that finds the most kinds of living things will keep the green flag for a term.''"}]'::jsonb, '[{"word": "face", "cn": "朝向"}, {"word": "living things", "cn": "生物"}, {"word": "flag", "cn": "旗"}]'::jsonb),
  -- U6 dialogue《Bring your own cup》74 词 · 37 秒
  ('fbc505ab-64df-e2c7-3c0a-d25d19ca4b5b', 9, 'junior_fltrp', 'wy9A', 'U6', 'Bring your own cup', '自带杯子(构词法 un-/-ful/-less/-ly · 省略引导词)', 'A: The tea shop near the gate has a new rule.
B: What is it?
A: If you bring your own cup, you pay two yuan less.
B: Useful. My old cup is not beautiful, but it is unbreakable.
A: Mine is a jam jar. It works perfectly.
B: So we save money and the shop uses fewer paper cups.
A: That is the kind of rule I like: helpful to everybody and painless.', 'A:校门口那家茶饮店有个新规定。B:什么规定?A:自带杯子,便宜两块。B:有用。我那个旧杯子不好看,但摔不烂。A:我用的是果酱瓶,好使得很。B:这样我们省了钱,店里也少用纸杯。A:这就是我喜欢的那种规定:对谁都有好处,还一点不费劲。', NULL, 'fable', 'dialogue', 37, 1, '[{"type": "choice", "q": "What happens if you bring your own cup?", "options": ["You pay two yuan less.", "You wait a shorter time.", "You get a paper cup too.", "You get a free cup of tea."], "answer": "A", "explanation": "''If you bring your own cup, you pay two yuan less.''"}, {"type": "choice", "q": "What does A use as a cup?", "options": ["A paper cup.", "A glass from school.", "A jam jar.", "A new bottle."], "answer": "C", "explanation": "''Mine is a jam jar. It works perfectly.''"}]'::jsonb, '[{"word": "unbreakable", "cn": "摔不烂的(un- + break + -able)"}, {"word": "painless", "cn": "不费劲的(pain + -less)"}, {"word": "jam jar", "cn": "果酱瓶"}]'::jsonb),
  -- U6 dialogue《The uniform swap》75 词 · 38 秒
  ('c2382b17-5ceb-55f6-ed4f-564be80b674d', 9, 'junior_fltrp', 'wy9A', 'U6', 'The uniform swap', '旧校服交换(构词法 re-/un-/-ful/-ly)', 'A: My school uniform is too short now.
B: Do not throw it away. There is a swap on Thursday.
A: A swap?
B: You bring the one you cannot wear and take one that fits. It is free.
A: Is it clean?
B: Everything is washed carefully before the day. Last term nobody was unhappy with it.
A: Then I will bring two. Reusing is cheaper than buying, and my mother will be thankful.', 'A:我的校服现在太短了。B:别扔。周四有一场交换。A:交换?B:你把穿不下的那件带来,换一件合身的,免费。A:干净吗?B:活动前都会仔细洗过。上学期没有一个人不满意。A:那我带两件。再利用比买新的便宜,我妈会很领情。', NULL, 'fable', 'dialogue', 38, 2, '[{"type": "choice", "q": "What do you do at the swap?", "options": ["Buy a cheap uniform.", "Give a uniform away and get nothing.", "Wash old uniforms for the school.", "Bring one you cannot wear and take one that fits."], "answer": "D", "explanation": "''You bring the one you cannot wear and take one that fits. It is free.''"}, {"type": "choice", "q": "Why will A''s mother be thankful?", "options": ["Because reusing is cheaper than buying.", "Because the uniform is new.", "Because A washed the clothes.", "Because the swap is on Thursday."], "answer": "A", "explanation": "''Reusing is cheaper than buying, and my mother will be thankful.''"}]'::jsonb, '[{"word": "swap", "cn": "交换(活动)"}, {"word": "reuse", "cn": "再利用(re- + use)"}, {"word": "thankful", "cn": "感激的(thank + -ful)"}]'::jsonb),
  -- U6 dialogue《The walking bus》78 词 · 39 秒
  ('96fa1912-f492-4fc5-f8e1-5df763fde617', 9, 'junior_fltrp', 'wy9A', 'U6', 'The walking bus', '步行上学小队(构词法 -ly/-less/-ful · if 条件)', 'A: Why are twelve of you walking together every morning?
B: It is our walking bus. We meet at the corner at seven twenty.
A: Does a teacher come?
B: Two parents come. They take turns weekly.
A: And if it rains?
B: We still walk. Rain is harmless if you have a coat.
A: Twelve fewer cars at the gate. That is a useful idea.
B: And the road is quieter, so it is safer for everyone.', 'A:你们十二个人怎么每天早上一起走?B:这是我们的「步行巴士」。我们七点二十在路口集合。A:有老师带队吗?B:两位家长,按周轮流。A:下雨怎么办?B:照走。只要有雨衣,雨没什么害处。A:校门口少了十二辆车,这主意真有用。B:路上也更安静,对谁都更安全。', NULL, 'fable', 'dialogue', 39, 2, '[{"type": "choice", "q": "Who comes with the students every morning?", "options": ["One teacher.", "Two parents, taking turns weekly.", "A bus driver.", "Nobody."], "answer": "B", "explanation": "''Two parents come. They take turns weekly.''"}, {"type": "choice", "q": "What does B say about rain?", "options": ["They walk faster.", "They take the bus instead.", "They wait at the corner.", "Rain is harmless if you have a coat."], "answer": "D", "explanation": "''We still walk. Rain is harmless if you have a coat.''"}]'::jsonb, '[{"word": "weekly", "cn": "每周地(week + -ly)"}, {"word": "harmless", "cn": "无害的(harm + -less)"}, {"word": "take turns", "cn": "轮流"}]'::jsonb),
  -- U6 passage《A week without plastic》115 词 · 58 秒
  ('c37a7ea4-a0cf-b48f-0714-14bdd4430dce', 9, 'junior_fltrp', 'wy9A', 'U6', 'A week without plastic', '独白·无塑一周(构词法 dis-/un-/re-/-ful/-ly)', 'Our class tried something for seven days: no new plastic. It sounded easy and it was not. On Monday I discovered that my bread, my pen and even my socks came wrapped in it. By Wednesday I was unhappy and ready to stop. Then our teacher said one useful thing: do not try to be perfect, try to be careful. So I changed three habits only. I took a cloth bag to the shop, I refilled my water bottle, and I bought bread that was not wrapped. At the end of the week our bin was half empty. The lesson was not really about plastic. It was about how quickly a habit can be rebuilt.', '我们班试了七天:不用新塑料。听起来容易,其实不然。周一我发现,我的面包、我的笔、甚至我的袜子,都是用它包着的。到周三我已经很烦、准备放弃了。这时老师说了一句有用的话:别想着做到完美,试着做到用心。于是我只改了三个习惯:去店里带布袋、把水瓶接满、买没有包装的面包。到那周结束,我们的垃圾桶空了一半。这堂课其实不是关于塑料的,而是关于一个习惯可以多快被重新建立起来。', NULL, 'fable', 'passage', 58, 3, '[{"type": "choice", "q": "What did the writer discover on Monday?", "options": ["The class rule was too easy.", "Plastic bags cost money.", "Bread, a pen and even socks came wrapped in plastic.", "The shop had no bread."], "answer": "C", "explanation": "''On Monday I discovered that my bread, my pen and even my socks came wrapped in it.''"}, {"type": "choice", "q": "What did the teacher advise?", "options": ["Ask the shop to change.", "Do not try to be perfect, try to be careful.", "Stop the plan at once.", "Use only paper bags."], "answer": "B", "explanation": "''do not try to be perfect, try to be careful.''"}]'::jsonb, '[{"word": "discover", "cn": "发现(dis- + cover)"}, {"word": "refill", "cn": "重新装满(re- + fill)"}, {"word": "rebuild", "cn": "重新建立(re- + build)"}]'::jsonb),
  -- U6 passage《The blue barrel》110 词 · 55 秒
  ('3cb74601-e9fd-9efa-85ee-baf910078999', 9, 'junior_fltrp', 'wy9A', 'U6', 'The blue barrel', '独白·接雨水的桶(构词法 -ful/-less/-ly · 省略引导词)', 'Behind our classroom there is a blue barrel that catches rain from the roof. It was put there by last year''s Year Nine, and it is the most useful thing they left us. One barrel holds two hundred litres. We use it for the plants along the wall and for washing the windows, so we never take clean drinking water for that. In a dry month the barrel is useless, of course, and we wait. But over a year it has saved more water than a whole class drinks. The best part is how simple it is: no power, no buttons, no repairs. It just waits for the sky, quietly.', '我们教室后面有一个蓝色的桶,接屋顶流下来的雨水。它是去年九年级留下的,也是他们留给我们最有用的东西。一桶能装两百升。我们用它浇墙边的花草、擦窗户,这样就不必用干净的饮用水做这些事。当然,干旱的月份里这桶毫无用处,我们就等着。但一年下来,它省下的水比一个班喝掉的还多。最妙的是它有多简单:不用电、没有按钮、不用修。它只是安静地等着天。', NULL, 'fable', 'passage', 55, 2, '[{"type": "choice", "q": "What do they use the rain water for?", "options": ["For the plants and for washing the windows.", "For the school kitchen.", "For the sports ground.", "For drinking in summer."], "answer": "A", "explanation": "''We use it for the plants along the wall and for washing the windows.''"}, {"type": "choice", "q": "What does the writer think is the best part?", "options": ["It is blue.", "It was free.", "It holds two hundred litres.", "How simple it is: no power, no buttons, no repairs."], "answer": "D", "explanation": "''The best part is how simple it is: no power, no buttons, no repairs.''"}]'::jsonb, '[{"word": "barrel", "cn": "桶"}, {"word": "useless", "cn": "没用的(use + -less)"}, {"word": "litre", "cn": "升"}]'::jsonb),
  -- U6 notice《Green Travel Month》119 词 · 60 秒
  ('18cb9ecd-bb1f-8123-0ac8-a27433bda879', 9, 'junior_fltrp', 'wy9A', 'U6', 'Green Travel Month', '通知·绿色出行月(构词法 un-/-less/-ly · so that 目的)', 'Good afternoon. October is our Green Travel Month. If you live within two kilometres of school, please walk or ride. Ask your parents to park at the market and walk the last part with you, so that the gate stays clear and safer for everyone. One unnecessary car trip a day adds up to twenty in a month. Each class will keep a weekly count on the board outside Room 210. The class with the highest number of green trips will plant a tree in the school garden in November. Careless parking will be reported to the office. Remember: a short trip on foot is not a small thing. It is the easiest change any of us can make.', '下午好。十月是我们的绿色出行月。如果你住在离学校两公里以内,请步行或骑车。请家长把车停在市场那边,陪你走完最后一段,好让校门口保持畅通、对所有人都更安全。一天一趟没必要的车程,一个月就是二十趟。各班在210室外的板上做每周统计。绿色出行次数最多的班级将在十一月于校园里种下一棵树。乱停车会上报到校办。记住:一段短短的步行不是小事,它是我们每个人最容易做到的改变。', NULL, 'fable', 'notice', 60, 1, '[{"type": "choice", "q": "What are parents asked to do?", "options": ["Plant a tree in November.", "Drive to the school gate.", "Park at the market and walk the last part.", "Wait outside Room 210."], "answer": "C", "explanation": "''Ask your parents to park at the market and walk the last part with you.''"}, {"type": "choice", "q": "What will the winning class do in November?", "options": ["Have a free trip.", "Plant a tree in the school garden.", "Keep the board for a term.", "Get a green flag."], "answer": "B", "explanation": "''The class with the highest number of green trips will plant a tree in the school garden in November.''"}]'::jsonb, '[{"word": "unnecessary", "cn": "没必要的(un- + necessary)"}, {"word": "careless", "cn": "粗心的,随意的(care + -less)"}, {"word": "add up to", "cn": "加起来达到"}]'::jsonb);

DO $$
DECLARE tot int; bad int;
BEGIN
  -- ① 总数 36
  SELECT count(*) INTO tot FROM public.junior_listening_exercises
   WHERE publisher='junior_fltrp' AND volume='wy9A';
  IF tot <> 36 THEN RAISE EXCEPTION 'total=% 期望 36', tot; END IF;

  -- ② 每单元恰好 6 篇,且体裁必须是 3 对话 + 2 独白 + 1 通知
  SELECT count(*) INTO bad FROM (
    SELECT unit FROM public.junior_listening_exercises
     WHERE publisher='junior_fltrp' AND volume='wy9A'
     GROUP BY unit
    HAVING count(*) <> 6
        OR count(*) FILTER (WHERE kind='dialogue') <> 3
        OR count(*) FILTER (WHERE kind='passage')  <> 2
        OR count(*) FILTER (WHERE kind='notice')   <> 1) t;
  IF bad <> 0 THEN RAISE EXCEPTION '单元数/体裁配比不符的单元数=%(应 6 篇=3+2+1)', bad; END IF;

  -- ③ 单元集合必须正好是 U1..U6(防错写 Starter 或漏单元)
  SELECT count(DISTINCT unit) INTO tot FROM public.junior_listening_exercises
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND unit IN ('U1','U2','U3','U4','U5','U6');
  IF tot <> 6 THEN RAISE EXCEPTION '单元集合不是 U1..U6,实得 % 个', tot; END IF;

  -- ④ 每篇必须 2 题,每题 4 个选项,答案必须是 A/B/C/D
  SELECT count(*) INTO bad FROM public.junior_listening_exercises
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND jsonb_array_length(questions) <> 2;
  IF bad <> 0 THEN RAISE EXCEPTION '题数不为 2 的篇=%', bad; END IF;

  SELECT count(*) INTO bad FROM public.junior_listening_exercises e
   WHERE e.publisher='junior_fltrp' AND e.volume='wy9A'
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(e.questions) x
                  WHERE jsonb_array_length(x->'options') <> 4
                     OR (x->>'answer') NOT IN ('A','B','C','D'));
  IF bad <> 0 THEN RAISE EXCEPTION '选项数≠4 或答案非 ABCD 的篇=%', bad; END IF;

  -- ⑤ 音色必须全 fable,audio_url 此刻必须全 NULL(音频由 pregenerate 之后回填)
  SELECT count(*) INTO bad FROM public.junior_listening_exercises
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND (speaker <> 'fable' OR audio_url IS NOT NULL);
  IF bad <> 0 THEN RAISE EXCEPTION '音色非 fable 或 audio_url 非空的篇=%', bad; END IF;

  -- ⑥ 文本字段不得为空,translation_cn 必须有(四册惯例:听力必配中译)
  SELECT count(*) INTO bad FROM public.junior_listening_exercises
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND (btrim(coalesce(transcript,'')) = '' OR btrim(coalesce(translation_cn,'')) = ''
          OR btrim(coalesce(title,'')) = '' OR btrim(coalesce(topic,'')) = '');
  IF bad <> 0 THEN RAISE EXCEPTION '有空文本字段的篇=%', bad; END IF;

  -- ⑦ 标题在本册内唯一(重名会让回填与抽听对不上号)
  SELECT count(*) INTO bad FROM (
    SELECT title FROM public.junior_listening_exercises
     WHERE publisher='junior_fltrp' AND volume='wy9A'
     GROUP BY title HAVING count(*) > 1) t;
  IF bad <> 0 THEN RAISE EXCEPTION '本册重名标题=% 个', bad; END IF;

  -- ⑧ 不得误伤其它册:与本事务开始前的快照逐数比对(不写死魔法数)
  SELECT count(*) INTO tot FROM public.junior_listening_exercises
   WHERE NOT (publisher='junior_fltrp' AND volume='wy9A');
  IF tot <> (SELECT n FROM _wy9a_guard) THEN
    RAISE EXCEPTION '本册以外的听力行数从 % 变成了 %,疑似误伤', (SELECT n FROM _wy9a_guard), tot;
  END IF;
END $$;

COMMIT;

-- ============================================================
-- 跑完必看:期望 6 行;total 全 6、dialogue 3、passage 2、notice 1、q_min=q_max=2、audio_null=6
-- ============================================================
SELECT unit,
       count(*) AS total,
       count(*) FILTER (WHERE kind='dialogue') AS dialogue,
       count(*) FILTER (WHERE kind='passage')  AS passage,
       count(*) FILTER (WHERE kind='notice')   AS notice,
       min(jsonb_array_length(questions)) AS q_min,
       max(jsonb_array_length(questions)) AS q_max,
       count(*) FILTER (WHERE audio_url IS NULL) AS audio_null,
       min(duration_sec) AS sec_min, max(duration_sec) AS sec_max
  FROM public.junior_listening_exercises
 WHERE publisher='junior_fltrp' AND volume='wy9A'
 GROUP BY unit ORDER BY unit;
